if (element.dataset.gridRedesigned) return;
element.dataset.gridRedesigned = 'true';

// Hide the original sidebar module
element.style.display = 'none';

// Get the list items
const items = element.querySelectorAll('.ListView--listView---8Ujq');
if (items.length === 0) return;

// Create the new grid module
const gridModule = document.createElement('section');
gridModule.setAttribute('aria-label', 'Product Reviews & Deals');
gridModule.setAttribute('data-testid', 'ContentMediaModule');
gridModule.style.cssText = 'grid-column: 1 / -1; margin-bottom: 24px;';

// Card wrapper
const card = document.createElement('div');
card.className = 'card Card--card--qJMOC Card--cardPadded--d1sUG';
card.style.cssText = 'background: #ffffff; border-radius: 12px; overflow: hidden; box-shadow: 0 2px 12px rgba(0,0,0,0.08);';

// Header
const header = document.createElement('header');
header.className = 'Card--cardHeader--AE3k1';
header.style.cssText = 'padding: 20px 24px 12px; border-bottom: 2px solid #f0f0f0;';
header.innerHTML = `
  <a class="Button--default--osTe5" href="https://weather.com/atmosphere" style="text-decoration:none;">
    <div class="Card--cardHeaderWrap--SAJFC" style="display:flex; align-items:center; justify-content:space-between;">
      <div>
        <p style="margin:0 0 4px 0; font-size:12px; font-weight:700; text-transform:uppercase; letter-spacing:1px; color:#0077c8;">Editorial Picks</p>
        <h2 class="Card--cardHeading--M6yBx" style="margin:0; font-size:22px; font-weight:800; color:#1a1a2e;">Product Reviews & Deals</h2>
      </div>
      <span style="color:#0077c8; font-size:14px; font-weight:600;">See all →</span>
    </div>
  </a>
`;

// Content area
const content = document.createElement('div');
content.className = 'Card--content--IOayG';
content.style.padding = '20px 24px 24px;';

// Grid container
const grid = document.createElement('div');
grid.style.cssText = 'display: grid; grid-template-columns: repeat(3, 1fr); gap: 20px;';

// Build grid cards from items
items.forEach(function(item) {
  const link = item.getAttribute('href') || '#';
  const imgEl = item.querySelector('.Image--intrinsicRatioElement--bFd9O');
  const titleEl = item.querySelector('.ListView--listViewTitle--fB8w3');

  if (!imgEl || !titleEl) return;

  const cardLink = document.createElement('a');
  cardLink.href = link;
  cardLink.style.cssText = 'display:flex; flex-direction:column; text-decoration:none; border-radius:10px; overflow:hidden; background:#f8f9fb; transition:transform 0.2s ease, box-shadow 0.2s ease; cursor:pointer;';

  cardLink.addEventListener('mouseenter', function() {
    cardLink.style.transform = 'translateY(-6px)';
    cardLink.style.boxShadow = '0 12px 32px rgba(0,0,0,0.15)';
  });
  cardLink.addEventListener('mouseleave', function() {
    cardLink.style.transform = '';
    cardLink.style.boxShadow = '';
  });

  // Image container with gradient overlay
  const imgContainer = document.createElement('div');
  imgContainer.style.cssText = 'position:relative; width:100%; padding-top:56.25%; overflow:hidden; background:linear-gradient(135deg, #667eea 0%, #764ba2 100%);';

  const newImg = document.createElement('img');
  newImg.src = imgEl.dataset.src || imgEl.src;
  newImg.style.cssText = 'position:absolute; top:0; left:0; width:100%; height:100%; object-fit:cover; transition:transform 0.3s ease;';

  cardLink.addEventListener('mouseenter', function() {
    newImg.style.transform = 'scale(1.05)';
  });
  cardLink.addEventListener('mouseleave', function() {
    newImg.style.transform = '';
  });

  // Badge overlay
  const badge = document.createElement('div');
  badge.style.cssText = 'position:absolute; top:10px; left:10px; background:rgba(0,119,200,0.9); color:#fff; font-size:10px; font-weight:700; text-transform:uppercase; letter-spacing:0.5px; padding:4px 10px; border-radius:4px; z-index:1;';
  badge.textContent = 'Review';

  imgContainer.appendChild(newImg);
  imgContainer.appendChild(badge);

  // Title area
  const titleArea = document.createElement('div');
  titleArea.style.cssText = 'padding:14px 16px; flex:1; display:flex; flex-direction:column; justify-content:center;';

  const titleText = document.createElement('p');
  titleText.style.cssText = 'margin:0; font-size:14px; font-weight:600; line-height:1.45; color:#1a1a2e;';
  titleText.textContent = titleEl.textContent;

  // Footer with "Read more" hint
  const cardFooter = document.createElement('div');
  cardFooter.style.cssText = 'padding:0 16px 14px; display:flex; align-items:center;';
  const readMore = document.createElement('span');
  readMore.style.cssText = 'font-size:12px; font-weight:600; color:#0077c8; opacity:0; transition:opacity 0.2s ease;';
  readMore.textContent = 'Read review →';

  cardLink.addEventListener('mouseenter', function() {
    readMore.style.opacity = '1';
  });
  cardLink.addEventListener('mouseleave', function() {
    readMore.style.opacity = '0';
  });

  cardFooter.appendChild(readMore);

  cardLink.appendChild(imgContainer);
  cardLink.appendChild(titleArea);
  cardLink.appendChild(titleText);
  cardLink.appendChild(cardFooter);

  grid.appendChild(cardLink);
});

content.appendChild(grid);
card.appendChild(header);
card.appendChild(content);
gridModule.appendChild(card);

// Insert into main content after the Top Stories module
const mainContent = document.querySelector('.region-main');
if (mainContent) {
  const topStories = mainContent.querySelector('[aria-label="TOP STORY"]');
  if (topStories && topStories.nextElementSibling) {
    mainContent.insertBefore(gridModule, topStories.nextElementSibling);
  } else if (topStories) {
    mainContent.insertBefore(gridModule, topStories.nextSibling);
  } else {
    mainContent.insertBefore(gridModule, mainContent.children[1]);
  }
}

